def bare(action):
    try: action()
    except Error: raise


def same_name(action):
    try: action()
    except Error as error: raise error


def wrapped(action):
    try: action()
    except Error as error: raise DomainError(error)


def caused(action):
    try: action()
    except Error as error: raise DomainError() from error


def suppressed(action):
    """Expose the public exception without displaying backend context."""
    try: action()
    except Error: raise DomainError() from None


def conditional(action, ready):
    try: action()
    except Error as error:
        if ready:
            raise DomainError() from error
        return None


def finalized(action, resource):
    try: action()
    except Error as error: raise DomainError() from error
    finally: resource.close()
